Room.the_wedged_trade_is_a_shuffle	tactic	by have hua : ∀ x, x ∈ u → x ≠ a := fun x hx => (by piece_seek) have hub : ∀ x, x ∈ u → x ≠ b := fun x hx => (by piece_seek) have hcons : Apart (a :: (v1 ++ b :: v2)) := (by piece_seek) cases hcons with | cons hafresh hvrest => have hv1a : ∀ x, x ∈ v1 → x ≠ a := fun x hx he => hafresh x ((by piece_seek)) he.symm have hv1b : ∀ x, x ∈ v1 → x ≠ b := fun x hx => (by piece_seek) have hbfresh : Apart (b :: v2) := (by piece_seek) cases hbfresh with | cons hbf _ => have hv2a : ∀ x, x ∈ v2 → x ≠ a := fun x hx he => hafresh x ((by piece_seek)) he.symm have hv2b : ∀ x, x ∈ v2 → x ≠ b := fun x hx he => hbf x hx he.symm have hmap : (u ++ a :: (v1 ++ b :: v2)).map (trade beq a b) = u ++ b :: (v1 ++ a :: v2) := by rw [(by piece_seek)] show u.map (trade beq a b) ++ trade beq a b a :: (v1 ++ b :: v2).map (trade beq a b) = u ++ b :: (v1 ++ a :: v2) rw [(by piece_seek), ((by piece_seek)).1, (by piece_seek)] show u ++ b :: (v1.map (trade beq a b) ++ trade beq a b b :: v2.map (trade beq a b)) = u ++ b :: (v1 ++ a :: v2) rw [(by piece_seek), ((by piece_seek)).2, (by piece_seek)] rw [hmap] refine (by piece_seek) exact ((List.Perm.cons b ((by piece_seek))).trans (List.Perm.swap a b (v1 ++ v2))).trans (List.Perm.cons a ((by piece_seek)))	by⏎  have hua : ∀ x, x ∈ u → x ≠ a := fun x hx =>⏎    (by piece_seek)⏎  have hub : ∀ x, x ∈ u → x ≠ b := fun x hx =>⏎    (by piece_seek)⏎  have hcons : Apart (a :: (v1 ++ b :: v2)) :=⏎    (by piece_seek)⏎  cases hcons with⏎  | cons hafresh hvrest =>⏎      have hv1a : ∀ x, x ∈ v1 → x ≠ a := fun x hx he =>⏎        hafresh x ((by piece_seek)) he.symm⏎      have hv1b : ∀ x, x ∈ v1 → x ≠ b := fun x hx =>⏎        (by piece_seek)⏎      have hbfresh : Apart (b :: v2) := (by piece_seek)⏎      cases hbfresh with⏎      | cons hbf _ =>⏎          have hv2a : ∀ x, x ∈ v2 → x ≠ a := fun x hx he =>⏎            hafresh x ((by piece_seek)) he.symm⏎          have hv2b : ∀ x, x ∈ v2 → x ≠ b := fun x hx he =>⏎            hbf x hx he.symm⏎          have hmap : (u ++ a :: (v1 ++ b :: v2)).map (trade beq a b)⏎              = u ++ b :: (v1 ++ a :: v2) := by⏎            rw [(by piece_seek)]⏎            show u.map (trade beq a b)⏎                ++ trade beq a b a :: (v1 ++ b :: v2).map (trade beq a b)⏎              = u ++ b :: (v1 ++ a :: v2)⏎            rw [(by piece_seek),⏎                ((by piece_seek)).1,⏎                (by piece_seek)]⏎            show u ++ b :: (v1.map (trade beq a b)⏎                ++ trade beq a b b :: v2.map (trade beq a b))⏎              = u ++ b :: (v1 ++ a :: v2)⏎            rw [(by piece_seek),⏎                ((by piece_seek)).2,⏎                (by piece_seek)]⏎          rw [hmap]⏎          refine (by piece_seek)⏎          exact ((List.Perm.cons b ((by piece_seek))).trans⏎            (List.Perm.swap a b (v1 ++ v2))).trans⏎            (List.Perm.cons a ((by piece_seek)))	
